solution.solution.cpp:
#include <cstdlib>
#include <string>
#include <vector>

struct Shape { int id; bool circle; int x, y, w, h; };

class Wheel
{
public:
    int add(int delta)
    {
        m_rest += delta;
        const int notches{ m_rest / 120 };      // integer division rounds towards zero
        m_rest -= notches * 120;
        return notches;
    }

private:
    int m_rest{ 0 };
};

int hitTest(const std::vector<Shape>& shapes, int x, int y)
{
    for (auto it{ shapes.rbegin() }; it != shapes.rend(); ++it)
    {
        const Shape& s{ *it };
        if (s.circle)
        {
            const long dx{ x - s.x }, dy{ y - s.y };
            if (dx * dx + dy * dy <= static_cast<long>(s.w) * s.w) return s.id;
        }
        else if (x >= s.x && x < s.x + s.w && y >= s.y && y < s.y + s.h) return s.id;
    }
    return -1;
}

class Drag
{
public:
    explicit Drag(int threshold) : m_threshold{ threshold } {}

    void down(int x, int y) { m_state = State::Pressed; m_x = x; m_y = y; }

    void move(int x, int y)
    {
        if (m_state == State::Pressed && (std::abs(x - m_x) > m_threshold || std::abs(y - m_y) > m_threshold)) m_state = State::Dragging;
    }

    bool up(int, int)
    {
        const bool was{ m_state == State::Dragging };
        m_state = State::Idle;
        return was;
    }

    void captureLost() { m_state = State::Idle; }
    bool dragging() const { return m_state == State::Dragging; }

    std::string state() const
    {
        switch (m_state)
        {
        case State::Idle: return "idle";
        case State::Pressed: return "pressed";
        case State::Dragging: return "dragging";
        }
        return "";
    }

private:
    enum class State { Idle, Pressed, Dragging };
    int m_threshold;
    State m_state{ State::Idle };
    int m_x{ 0 }, m_y{ 0 };
};

unitTests:
TEST("mouse wheel") { Wheel w; CHECK_EQ(w.add(120), 1); CHECK_EQ(w.add(-360), -3); CHECK_EQ(w.add(240), 2); }
TEST("precision touchpad") { Wheel w; int total = 0; for (int i = 0; i < 7; ++i) total += w.add(30); CHECK_EQ(total, 1); total += w.add(-50); CHECK_EQ(total, 1); CHECK_EQ(w.add(-100), 0); CHECK_EQ(w.add(-80), -1); CHECK_EQ(w.add(70), 0); }
TEST("hit testing") {
    const std::vector<Shape> s{ { 1, false, 0, 0, 100, 100 }, { 2, true, 50, 50, 20, 0 }, { 3, false, 90, 90, 30, 30 } };
    CHECK_EQ(hitTest(s, 10, 10), 1); CHECK_EQ(hitTest(s, 55, 55), 2); CHECK_EQ(hitTest(s, 70, 50), 2); CHECK_EQ(hitTest(s, 95, 95), 3);
    CHECK_EQ(hitTest(s, 100, 10), -1); CHECK_EQ(hitTest(s, 120, 95), -1); CHECK_EQ(hitTest(s, 71, 50), 1);
}
TEST("a click is not a drag") { Drag d{ 4 }; d.down(10, 10); d.move(13, 14); CHECK_EQ(d.state(), std::string("pressed")); CHECK(!d.up(13, 14)); CHECK_EQ(d.state(), std::string("idle")); }
TEST("a real drag") { Drag d{ 4 }; d.down(10, 10); d.move(10, 15); CHECK(d.dragging()); d.move(10, 10); CHECK(d.dragging()); CHECK(d.up(10, 10)); CHECK(!d.dragging()); }
TEST("capture lost") { Drag d{ 4 }; d.down(0, 0); d.move(-20, 0); CHECK(d.dragging()); d.captureLost(); CHECK_EQ(d.state(), std::string("idle")); CHECK(!d.up(0, 0)); d.move(50, 50); CHECK_EQ(d.state(), std::string("idle")); }

